/* PROPHOTO — спільна шапка та бургер-меню для всіх сайтів екосистеми.
   Підключення:  <script src="prophoto-nav.js" data-site="studio|academy|shop" data-page="cyclorama|content|makeup|smm|..." data-mode="fixed|static"></script>
   Усі адреси в одному місці — блок URLS нижче. */
(function () {
  var URLS = {
    main:     'https://kameneva-tn.github.io/PROPHOTO/',            // головна сторінка екосистеми (ще не створена)
    studio:   'https://kameneva-tn.github.io/PROPHOTOHUB/',
    cyclorama:'https://kameneva-tn.github.io/PROPHOTOHUB/halls/cyclorama.html',
    content:  'https://kameneva-tn.github.io/PROPHOTOHUB/halls/content-studio.html',
    makeup:   'https://kameneva-tn.github.io/PROPHOTOHUB/halls/makeup-room.html',
    academy:  'https://kameneva-tn.github.io/PROPHOTO-ACADEMY/',
    smm:      'https://kameneva-tn.github.io/PRO-PHOTO-SMM/',
    visual:   'https://www.prophotoacademy.com.ua/visual-content',
    shop:     'https://kameneva-tn.github.io/PROPHOTO-SHOP/',
    contacts: 'https://kameneva-tn.github.io/PROPHOTO-ACADEMY/#contacts'
  };

  var LOGOS = {
    studio:  'data:image/png;base64,',
    academy: 'data:image/png;base64,',
    shop:    'data:image/svg+xml;utf8,' + encodeURIComponent(
      '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 160">' +
      '<rect x="6" y="18" width="118" height="118" rx="22" fill="#f2f0eb"/>' +
      '<circle cx="65" cy="77" r="40" fill="#1c1a19"/><circle cx="65" cy="77" r="24" fill="#f2f0eb"/><circle cx="65" cy="77" r="11" fill="#1c1a19"/>' +
      '<text x="140" y="70" font-family="Inter,Arial,sans-serif" font-weight="900" font-size="54" fill="#f2f0eb" letter-spacing="-1">PRO</text>' +
      '<text x="140" y="122" font-family="Inter,Arial,sans-serif" font-weight="900" font-size="54" fill="#f2f0eb" letter-spacing="-1">PHOTO</text>' +
      '<text x="330" y="152" font-family="Inter,Arial,sans-serif" font-weight="700" font-size="28" fill="#f2f0eb" text-anchor="end">shop</text>' +
      '</svg>')
  };

  var SITES = {
    studio: {
      name: 'PROPHOTO STUDIO', home: URLS.studio, logo: LOGOS.studio, logoAlt: 'Pro Photo Studio',
      links: [['Циклорама', URLS.cyclorama, 'cyclorama'], ['Контент зал', URLS.content, 'content'], ['Гримерна', URLS.makeup, 'makeup']]
    },
    academy: {
      name: 'PROPHOTO ACADEMY', home: URLS.academy, logo: LOGOS.academy, logoAlt: 'Pro Photo Academy',
      links: [['Воркшопи', URLS.academy + '#workshops', 'workshops'], ['Курси', URLS.academy + '#education', 'courses'], ['Корпоративне навчання', URLS.academy + '#corporate', 'corporate']]
    },
    shop: {
      name: 'PROPHOTO SHOP', home: URLS.shop, logo: LOGOS.shop, logoAlt: 'Pro Photo Shop',
      links: []
    }
  };

  var MENU = [
    { key: 'studio',  head: 'PROPHOTO', tail: 'STUDIO',  href: URLS.studio,
      items: [['Циклорама', URLS.cyclorama, 'cyclorama'], ['Контент зал', URLS.content, 'content'], ['Гримерна', URLS.makeup, 'makeup']] },
    { key: 'academy', head: 'PROPHOTO', tail: 'ACADEMY', href: URLS.academy,
      items: [['Інстаграм, що продає', URLS.smm, 'smm'], ['Зйомка на камеру і телефон', URLS.visual, 'visual']] },
    { key: 'shop',    head: 'PROPHOTO', tail: 'SHOP',    href: URLS.shop,
      items: [['Магазин обладнання', URLS.shop, 'shop']] }
  ];

  // Тимчасове просте меню для сайту студії (data-menu="site")
  var SITE_MENU = {
    studio: [
      ['PROPHOTO HUB', URLS.studio, 'home'],
      ['Про нас', URLS.studio + '#about', 'about'],
      ['Циклорама', URLS.cyclorama, 'cyclorama'],
      ['Контент зал', URLS.content, 'content'],
      ['Гримерна', URLS.makeup, 'makeup'],
      ['Контакти', URLS.studio + '#contacts', 'contacts']
    ]
  };

  var CSS = '\
@import url("https://fonts.googleapis.com/css2?family=Inter:wght@300;400;700;900&display=swap");\
.pp-nav{--pp-ink:#f2f0eb;--pp-dim:#6f6d6a;--pp-bg:#1c1a19;font-family:Inter,Arial,sans-serif;color:var(--pp-ink);left:0;right:0;top:0;z-index:900;box-sizing:border-box}\
.pp-nav *{box-sizing:border-box}\
.pp-nav--fixed{position:fixed;background:linear-gradient(to bottom,rgba(20,18,17,.85),rgba(20,18,17,0));transition:background .3s}\
.pp-nav--fixed.pp-nav--solid{background:var(--pp-bg)}\
.pp-nav--static{position:sticky;background:var(--pp-bg)}\
.pp-nav--top{position:relative;background:var(--pp-bg)}\
.pp-nav__bar{display:grid;grid-template-columns:1fr auto 1fr;align-items:center;gap:24px;padding:22px 40px 18px;max-width:1440px;margin:0 auto}\
.pp-nav__logo{display:block;line-height:0;justify-self:start}\
.pp-nav__logo img{height:52px;width:auto;display:block}\
.pp-nav__links{display:flex;gap:clamp(24px,4vw,64px);justify-content:center}\
.pp-nav__links a{color:var(--pp-ink);text-decoration:none;text-transform:uppercase;font-weight:300;font-size:14px;letter-spacing:.12em;opacity:.9;transition:opacity .2s;white-space:nowrap}\
.pp-nav__links a:hover,.pp-nav__links a.is-on{opacity:1;text-decoration:underline;text-underline-offset:7px;text-decoration-thickness:1px}\
.pp-nav__burger{justify-self:end;width:44px;height:44px;display:flex;align-items:center;justify-content:center;cursor:pointer;background:none;border:0;padding:0;border-radius:50%;transition:background .25s;position:relative;z-index:930}\
.pp-nav__burger:hover{background:rgba(255,255,255,.08)}\
.pp-nav__burger:focus-visible{outline:2px solid var(--pp-ink);outline-offset:2px}\
.pp-nav__burger i{display:block;width:26px;height:18px;position:relative}\
.pp-nav__burger i span{position:absolute;left:0;width:100%;height:3px;background:var(--pp-ink);border-radius:1px;transition:transform .3s cubic-bezier(.4,0,.2,1),opacity .2s,top .3s cubic-bezier(.4,0,.2,1)}\
.pp-nav__burger i span:nth-child(1){top:0}.pp-nav__burger i span:nth-child(2){top:7.5px}.pp-nav__burger i span:nth-child(3){top:15px}\
.pp-nav__burger.open i span:nth-child(1){top:7.5px;transform:rotate(45deg)}\
.pp-nav__burger.open i span:nth-child(2){opacity:0;transform:scaleX(0)}\
.pp-nav__burger.open i span:nth-child(3){top:7.5px;transform:rotate(-45deg)}\
.pp-nav--fixed .pp-nav__line{display:none}\
.pp-nav__line{height:1px;background:rgba(255,255,255,.35);max-width:1360px;margin:0 40px}\
@media (min-width:1441px){.pp-nav__line{margin:0 auto}}\
.pp-menu{position:fixed;inset:0;z-index:920;background:rgba(12,11,10,.97);backdrop-filter:blur(6px);-webkit-backdrop-filter:blur(6px);opacity:0;visibility:hidden;transition:opacity .4s ease,visibility .4s;display:flex;flex-direction:column;align-items:center;justify-content:center;font-family:Inter,Arial,sans-serif;padding:80px 40px 40px;overflow:auto}\
.pp-menu.open{opacity:1;visibility:visible}\
.pp-menu__inner{display:flex;gap:clamp(40px,5vw,90px);flex-wrap:wrap;justify-content:center;max-width:1200px}\
.pp-menu__col{min-width:220px;opacity:0;translate:0 24px;transition:opacity .5s ease,translate .6s cubic-bezier(.16,1,.3,1)}\
.pp-menu.open .pp-menu__col{opacity:1;translate:0 0}\
.pp-menu.open .pp-menu__col:nth-child(1){transition-delay:.05s}.pp-menu.open .pp-menu__col:nth-child(2){transition-delay:.12s}.pp-menu.open .pp-menu__col:nth-child(3){transition-delay:.19s}\
.pp-menu__head{display:block;text-decoration:none;font-size:clamp(22px,2.4vw,34px);font-weight:900;letter-spacing:-.01em;color:#f2f0eb;margin-bottom:26px;white-space:nowrap}\
.pp-menu__head span{font-weight:300;color:#8a8886;transition:color .2s}\
.pp-menu__head:hover span,.pp-menu__head.is-on span{color:#f2f0eb}\
.pp-menu__link{display:block;color:#7a7876;text-decoration:none;text-transform:uppercase;font-weight:300;font-size:clamp(15px,1.4vw,20px);letter-spacing:.04em;line-height:1.25;padding:9px 0;transition:color .2s,padding-left .2s;max-width:18ch}\
.pp-menu__link:hover{color:#f2f0eb;padding-left:6px}\
.pp-menu__link.is-on{color:#f2f0eb}\
.pp-menu__site{display:flex;flex-direction:column;gap:6px;align-items:flex-start}\
.pp-menu__site a{color:#8a8886;text-decoration:none;text-transform:uppercase;font-weight:300;font-size:clamp(24px,3.4vw,44px);letter-spacing:.02em;line-height:1.25;padding:6px 0;transition:color .2s,padding-left .2s}\
.pp-menu__site a:first-child{font-weight:900;color:#f2f0eb;letter-spacing:-.01em}\
.pp-menu__site a:hover,.pp-menu__site a.is-on{color:#f2f0eb;padding-left:8px}\
.pp-menu__foot{margin-top:70px;display:flex;gap:40px;flex-wrap:wrap;justify-content:center;opacity:0;transition:opacity .5s .3s}\
.pp-menu.open .pp-menu__foot{opacity:1}\
.pp-menu__foot a{color:#8a8886;text-decoration:none;text-transform:uppercase;font-size:12px;letter-spacing:.16em;font-weight:400;transition:color .2s}\
.pp-menu__foot a:hover{color:#f2f0eb}\
.pp-menu__foot a b{color:#f2f0eb;font-weight:900;letter-spacing:.02em}\
@media (max-width:960px){.pp-nav__bar{grid-template-columns:auto 1fr auto;padding:16px 20px 14px}.pp-nav__links{display:none}.pp-nav__logo img{height:40px}.pp-nav__line{margin:0 20px}\
  .pp-menu{padding:80px 24px 40px;justify-content:flex-start}.pp-menu__inner{flex-direction:column;gap:36px;align-items:flex-start}.pp-menu__col{min-width:0}.pp-menu__head{margin-bottom:12px}.pp-menu__link{max-width:none}.pp-menu__link:hover{padding-left:0}.pp-menu__foot{justify-content:flex-start;margin-top:48px}}\
body.pp-menu-lock{overflow:hidden}';

  /* ---------- побудова ---------- */
  var script = document.currentScript;
  var siteKey = (script && script.getAttribute('data-site')) || 'studio';
  var page = (script && script.getAttribute('data-page')) || '';
  var mode = (script && script.getAttribute('data-mode')) || 'fixed';
  var menuKind = (script && script.getAttribute('data-menu')) || 'ecosystem';
  var site = SITES[siteKey] || SITES.studio;
  var mount = document.getElementById('prophoto-nav');

  var style = document.createElement('style');
  style.textContent = CSS;
  document.head.appendChild(style);

  function esc(s) { return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/"/g, '&quot;'); }

  var links = site.links.map(function (l) {
    return '<a href="' + esc(l[1]) + '"' + (l[2] === page ? ' class="is-on"' : '') + '>' + esc(l[0]) + '</a>';
  }).join('');

  var nav = document.createElement('header');
  nav.className = 'pp-nav pp-nav--' + mode;
  nav.innerHTML =
    '<div class="pp-nav__bar">' +
      '<a class="pp-nav__logo" href="' + esc(site.home) + '" aria-label="' + esc(site.logoAlt) + '"><img src="' + site.logo + '" alt="' + esc(site.logoAlt) + '"></a>' +
      '<nav class="pp-nav__links" aria-label="' + esc(site.name) + '">' + links + '</nav>' +
      '<button class="pp-nav__burger" id="ppBurger" aria-label="Меню" aria-expanded="false" aria-controls="ppMenu"><i><span></span><span></span><span></span></i></button>' +
    '</div><div class="pp-nav__line"></div>';

  var cols = MENU.map(function (c) {
    var items = c.items.map(function (it) {
      return '<a class="pp-menu__link' + (it[2] === page ? ' is-on' : '') + '" href="' + esc(it[1]) + '">' + esc(it[0]) + '</a>';
    }).join('');
    return '<div class="pp-menu__col"><a class="pp-menu__head' + (c.key === siteKey ? ' is-on' : '') + '" href="' + esc(c.href) + '">' + c.head + '<span>' + c.tail + '</span></a>' + items + '</div>';
  }).join('');

  var menu = document.createElement('div');
  menu.className = 'pp-menu';
  menu.id = 'ppMenu';
  menu.setAttribute('aria-hidden', 'true');
  if (menuKind === 'site' && SITE_MENU[siteKey]) {
    menu.innerHTML = '<nav class="pp-menu__site">' + SITE_MENU[siteKey].map(function (l) {
      return '<a href="' + esc(l[1]) + '"' + (l[2] === page ? ' class="is-on"' : '') + '>' + esc(l[0]) + '</a>';
    }).join('') + '</nav>';
  } else {
    menu.innerHTML =
      '<div class="pp-menu__inner">' + cols + '</div>' +
      '<div class="pp-menu__foot"><a href="' + esc(URLS.main) + '"><b>PROPHOTO</b> — головна</a><a href="' + esc(URLS.contacts) + '">Контакти</a></div>';
  }
  // закриваємо меню при кліку на якір на цій же сторінці
  menu.addEventListener('click', function (e) { var a = e.target.closest('a'); if (a && a.getAttribute('href').indexOf('#') !== -1) setTimeout(function () { setOpen(false); }, 50); });

  if (mount) { mount.appendChild(nav); } else { document.body.insertBefore(nav, document.body.firstChild); }
  document.body.appendChild(menu);

  /* ---------- поведінка ---------- */
  var burger = document.getElementById('ppBurger');
  function setOpen(o) {
    burger.classList.toggle('open', o);
    menu.classList.toggle('open', o);
    burger.setAttribute('aria-expanded', String(o));
    menu.setAttribute('aria-hidden', String(!o));
    document.body.classList.toggle('pp-menu-lock', o);
  }
  burger.addEventListener('click', function () { setOpen(!menu.classList.contains('open')); });
  // у режимі fixed: після прокрутки за перший екран шапка стає суцільно чорною,
  // щоб білий логотип не губився на світлих розділах
  if (mode === 'fixed') {
    var solid = function () { nav.classList.toggle('pp-nav--solid', window.scrollY > window.innerHeight * 0.6); };
    window.addEventListener('scroll', solid, { passive: true }); solid();
  }
  menu.addEventListener('click', function (e) { if (e.target === menu) setOpen(false); });
  document.addEventListener('keydown', function (e) { if (e.key === 'Escape' && menu.classList.contains('open')) setOpen(false); });
})();
